"""Build the final HTML report from precomputed data."""
import pickle
import pandas as pd
import numpy as np

with open('/app/_report_payload.pkl', 'rb') as f:
    P = pickle.load(f)

stats_df = P['stats_df']
room_pct = P['room_pct']
price_by_rt = P['price_by_rt']
recent_share = P['recent_share']
charts = P['charts']

C = P  # shorthand for scalars

def kpi_card(label, value, subtitle="", color="#1f4e79"):
    return f'''<div class="kpi-card">
      <div class="kpi-value" style="color:{color}">{value}</div>
      <div class="kpi-label">{label}</div>
      {f'<div class="kpi-sub">{subtitle}</div>' if subtitle else ''}
    </div>'''

def data_table(df_rows, headers, align=None):
    if align is None:
        align = ['left'] * len(headers)
    hdr = ''.join(f'<th style="text-align:{a}">{h}</th>' for h, a in zip(headers, align))
    rows = ''
    for row in df_rows:
        cells = ''.join(
            f'<td style="text-align:{align[i]}">{row[i]}</td>'
            for i in range(len(row))
        )
        rows += f'<tr>{cells}</tr>\n'
    return f'<table><thead><tr>{hdr}</tr></thead><tbody>{rows}</tbody></table>'

def img_tag(key, alt=''):
    return f'<img src="data:image/png;base64,{charts[key]}" alt="{alt}" class="chart-img">'

# --- Build overview table ---
overview_rows = []
for city in stats_df.sort_values('listings', ascending=False).index:
    r = stats_df.loc[city]
    mp = f"${r['median_price']:,.0f}" if pd.notna(r['median_price']) else '<span class="missing">N/A*</span>'
    overview_rows.append([
        city,
        f"{int(r['listings']):,}",
        mp,
        f"${r['mean_price']:,.0f}" if pd.notna(r['mean_price']) else '<span class="missing">N/A*</span>',
        f"{r['eh_share']:.1f}%",
        f"{r['pro_host_share']:.1f}%",
        f"{r['avg_rpm']:.2f}" if pd.notna(r['avg_rpm']) else 'N/A',
        f"{r['avg_avail']:.0f}",
    ])

overview_table = data_table(
    overview_rows,
    ['City', 'Listings', 'Median Price', 'Mean Price', 'Entire Home %', 'Pro Host %', 'Avg Rev/Mo', 'Avg Avail (days)'],
    ['left', 'right', 'right', 'right', 'right', 'right', 'right', 'right']
)

# --- Build price-by-room-type table ---
price_rt_rows = []
for city in stats_df['median_price'].sort_values(ascending=False).dropna().index:
    row = [city]
    for rt in ['Entire home/apt', 'Private room', 'Hotel room', 'Shared room']:
        if rt in price_by_rt.columns and city in price_by_rt.index and pd.notna(price_by_rt.loc[city, rt]):
            row.append(f"${price_by_rt.loc[city, rt]:,.0f}")
        else:
            row.append('—')
    price_rt_rows.append(row)

price_rt_table = data_table(
    price_rt_rows,
    ['City', 'Entire Home/Apt', 'Private Room', 'Hotel Room', 'Shared Room'],
    ['left', 'right', 'right', 'right', 'right']
)

# --- Room-type composition table ---
room_rows = []
for city in room_pct.index:
    row = [city]
    for rt in ['Entire home/apt', 'Private room', 'Hotel room', 'Shared room']:
        if rt in room_pct.columns:
            row.append(f"{room_pct.loc[city, rt]:.1f}%")
        else:
            row.append('—')
    room_rows.append(row)

room_table = data_table(
    room_rows,
    ['City', 'Entire Home/Apt', 'Private Room', 'Hotel Room', 'Shared Room'],
    ['left', 'right', 'right', 'right', 'right']
)

# Pro host detail table
pro_rows = []
for city in stats_df['pro_host_share'].sort_values(ascending=False).index:
    r = stats_df.loc[city]
    pro_rows.append([
        city,
        f"{r['pro_host_share']:.1f}%",
        f"{r['eh_share']:.1f}%",
        f"{int(r['listings']):,}",
    ])

pro_table = data_table(
    pro_rows,
    ['City', 'Pro Host Share (≥5 listings)', 'Entire Home %', 'Total Listings'],
    ['left', 'right', 'right', 'right']
)

# Demand table
demand_rows = []
for city in stats_df['avg_rpm'].sort_values(ascending=False).dropna().index:
    r = stats_df.loc[city]
    rec = recent_share[city] if city in recent_share.index else 0
    demand_rows.append([
        city,
        f"{r['avg_rpm']:.2f}",
        f"{r['reviews_ltm_avg']:.1f}",
        f"{rec:.1f}%",
        f"{int(r['reviews_total']):,}",
    ])

demand_table = data_table(
    demand_rows,
    ['City', 'Avg Rev/Month', 'Avg Reviews (LTM)', 'Active Listings (%)', 'Total Reviews'],
    ['left', 'right', 'right', 'right', 'right']
)

# Availability table
avail_rows = []
for city in stats_df['avg_avail'].sort_values(ascending=False).index:
    r = stats_df.loc[city]
    avail_rows.append([
        city,
        f"{r['avg_avail']:.0f}",
        f"{r['avg_min_nights']:.0f}",
        f"{int(r['listings']):,}",
    ])

avail_table = data_table(
    avail_rows,
    ['City', 'Mean Availability (d/y)', 'Median Min. Nights', 'Total Listings'],
    ['left', 'right', 'right', 'right']
)

# --- cities with pricing for narrative ---
priced_cities = stats_df['median_price'].dropna().sort_values(ascending=False)
# exclude Bangkok from narrative comparisons due to data quality issues
clean_priced = priced_cities.drop('Bangkok', errors='ignore')
most_exp = clean_priced.index[0] if len(clean_priced) else 'N/A'
most_exp_v = clean_priced.iloc[0] if len(clean_priced) else 0
least_exp = clean_priced.index[-1] if len(clean_priced) else 'N/A'
least_exp_v = clean_priced.iloc[-1] if len(clean_priced) else 0

# --- Write HTML ---
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Global Airbnb Market Comparison: Cross-City Analysis</title>
<style>
  :root {{
    --blue: #1f4e79; --light-blue: #e8f0fe; --accent: #d97706;
    --success: #059669; --danger: #dc2626; --gray: #6b7280;
    --bg: #fafbfc; --card: #ffffff; --border: #e5e7eb;
    --text: #1e293b; --text-light: #64748b;
  }}
  *, *::before, *::after {{ box-sizing: border-box; margin: 0; padding: 0; }}
  html {{ scroll-behavior: smooth; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg); color: var(--text); line-height: 1.65;
    font-size: 15px;
  }}
  .container {{ max-width: 1060px; margin: 0 auto; padding: 40px 24px; }}
  /* ---- Header ---- */
  .report-header {{
    background: linear-gradient(135deg, var(--blue) 0%, #0c3557 100%);
    color: white; padding: 50px 40px 40px; border-radius: 12px;
    margin-bottom: 32px; position: relative; overflow: hidden;
  }}
  .report-header::after {{
    content: ''; position: absolute; top: -60px; right: -60px;
    width: 280px; height: 280px; background: rgba(255,255,255,0.04);
    border-radius: 50%;
  }}
  .report-header h1 {{ font-size: 2em; font-weight: 700; margin-bottom: 10px; }}
  .report-header p {{ opacity: 0.85; font-size: 1.05em; max-width: 700px; }}
  .meta-row {{ display: flex; gap: 24px; margin-top: 20px; font-size: 0.88em; opacity: 0.7; flex-wrap: wrap; }}
  /* ---- TOC ---- */
  .toc {{
    background: var(--card); border: 1px solid var(--border); border-radius: 10px;
    padding: 24px 32px; margin-bottom: 32px;
  }}
  .toc h3 {{ margin-bottom: 12px; font-size: 1.05em; color: var(--blue); }}
  .toc ol {{ padding-left: 22px; columns: 2; column-gap: 40px; }}
  .toc li {{ margin-bottom: 6px; }}
  .toc a {{ color: var(--blue); text-decoration: none; }}
  .toc a:hover {{ text-decoration: underline; }}
  /* ---- Sections ---- */
  .section {{
    background: var(--card); border: 1px solid var(--border); border-radius: 10px;
    padding: 32px 36px; margin-bottom: 28px;
  }}
  .section h2 {{
    font-size: 1.45em; color: var(--blue); margin-bottom: 8px;
    border-bottom: 2px solid var(--light-blue); padding-bottom: 8px;
  }}
  .section h3 {{ font-size: 1.1em; color: var(--text); margin: 22px 0 8px; }}
  .section p {{ margin-bottom: 14px; }}
  /* ---- KPI cards ---- */
  .kpi-grid {{
    display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px; margin: 20px 0;
  }}
  .kpi-card {{
    background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
    padding: 18px 16px; text-align: center;
  }}
  .kpi-value {{ font-size: 1.75em; font-weight: 700; }}
  .kpi-label {{ font-size: 0.82em; color: var(--text-light); margin-top: 4px; }}
  .kpi-sub {{ font-size: 0.75em; color: var(--gray); margin-top: 2px; }}
  /* ---- Tables ---- */
  table {{
    width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 0.9em;
  }}
  thead {{ background: var(--light-blue); }}
  th {{ padding: 10px 14px; font-weight: 600; color: var(--blue); white-space: nowrap; }}
  td {{ padding: 10px 14px; border-bottom: 1px solid var(--border); }}
  tbody tr:hover {{ background: #f8fafc; }}
  /* ---- Charts ---- */
  .chart-img {{ width: 100%; border-radius: 6px; margin: 16px 0; }}
  .chart-pair {{ display: grid; grid-template-columns: 1fr; gap: 20px; }}
  /* ---- Callout ---- */
  .callout {{
    border-left: 4px solid var(--accent); background: #fffbeb;
    padding: 14px 18px; border-radius: 0 8px 8px 0; margin: 16px 0;
    font-size: 0.92em; color: #92400e;
  }}
  .callout.info {{ border-color: var(--blue); background: var(--light-blue); color: var(--blue); }}
  .callout.red {{ border-color: var(--danger); background: #fef2f2; color: #991b1b; }}
  .missing {{ color: var(--danger); font-style: italic; }}
  /* ---- Key Takeaways ---- */
  .takeaway-list {{ list-style: none; padding: 0; counter-reset: tk; }}
  .takeaway-list li {{
    counter-increment: tk; position: relative; padding: 16px 16px 16px 56px;
    background: var(--bg); border: 1px solid var(--border); border-radius: 8px;
    margin-bottom: 12px;
  }}
  .takeaway-list li::before {{
    content: counter(tk); position: absolute; left: 16px; top: 16px;
    width: 28px; height: 28px; background: var(--blue); color: white;
    border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 0.9em;
  }}
  .footer {{
    text-align: center; padding: 24px; color: var(--text-light); font-size: 0.82em;
  }}
  @media (max-width: 680px) {{
    .container {{ padding: 16px; }}
    .section {{ padding: 20px; }}
    .toc ol {{ columns: 1; }}
  }}
</style>
</head>
<body>
<div class="container">

<!-- HEADER -->
<div class="report-header">
  <h1>Global Airbnb Market Comparison</h1>
  <p>Pricing, Supply &amp; Guest Demand Across Major Cities &mdash; A cross-market analysis for hospitality industry analysts and short-term rental strategists</p>
  <div class="meta-row">
    <span>Data snapshot: {C['scrape_date']}</span>
    <span>Listings analyzed: {C['total']:,}</span>
    <span>Cities: {len(stats_df)}</span>
    <span>Report generated: April 2026</span>
  </div>
</div>

<div class="callout red">
  <strong>Data Coverage Note</strong> &mdash; The source dataset contains <strong>7 of 10 intended cities</strong> (New York, Tokyo, and Los Angeles are absent). Additionally, <strong>Paris and Sydney have no price data</strong>, and <strong>Bangkok prices appear to be in local currency (THB)</strong> rather than USD. These limitations are flagged throughout the report. Price-based analyses exclude cities without reliable pricing.
</div>

<!-- TOC -->
<div class="toc">
  <h3>Contents</h3>
  <ol>
    <li><a href="#market-overview">Global Market Overview</a></li>
    <li><a href="#pricing-analysis">Pricing Dynamics Across Cities</a></li>
    <li><a href="#supply-structure">Supply Structure &amp; Host Concentration</a></li>
    <li><a href="#guest-demand">Guest Demand &amp; Review Activity</a></li>
    <li><a href="#availability-minimumnights">Availability &amp; Booking Constraints</a></li>
    <li><a href="#key-takeaways">Key Takeaways &amp; Strategic Implications</a></li>
  </ol>
</div>

<!-- SECTION 1: MARKET OVERVIEW -->
<div class="section" id="market-overview">
  <h2>1. Global Market Overview</h2>
  <p>The dataset comprises <strong>{C['total']:,} active Airbnb listings</strong> across seven major global cities, scraped on {C['scrape_date']}. London and Paris dominate in sheer supply, together accounting for over 61% of all listings analyzed.</p>

  <div class="kpi-grid">
    {kpi_card("Total Listings", f"{C['total']:,}", "Across 7 cities")}
    {kpi_card("Largest Market", f"{int(C['biggest_market_n']):,}", C['biggest_market'], "#2563eb")}
    {kpi_card("Smallest Market", f"{int(C['smallest_market_n']):,}", C['smallest_market'], "#9333ea")}
    {kpi_card("Price Coverage", f"{C['price_coverage']:.0f}%", "Listings with price data", "#d97706")}
  </div>

  {img_tag('listings', 'Listings per city')}

  <h3>Market Summary Table</h3>
  {overview_table}
  <p class="callout info"><strong>*N/A</strong> — Paris ({stats_df.loc["Paris","listings"]:,} listings) and Sydney ({stats_df.loc["Sydney","listings"]:,} listings) have zero price data in the source file. All pricing metrics for these cities are unavailable.</p>
</div>

<!-- SECTION 2: PRICING ANALYSIS -->
<div class="section" id="pricing-analysis">
  <h2>2. Pricing Dynamics Across Cities</h2>
  <p>Pricing is the most strategically important metric for market-entry and investment decisions. Among cities with reliable price data, <strong>{most_exp}</strong> commands the highest median nightly rate at <strong>${most_exp_v:,.0f}</strong>, while <strong>{least_exp}</strong> is the most affordable at <strong>${least_exp_v:,.0f}</strong> — a {most_exp_v/least_exp_v:.1f}x differential.</p>

  <div class="callout red">
    <strong>Bangkok Data Quality Warning</strong> — Bangkok's median price of $1,400 is orders of magnitude above comparable Asian markets, strongly suggesting prices are in Thai Baht (1 USD ≈ 35 THB). If converted, the median would be approximately <strong>$40 USD</strong>, making it by far the most affordable market. Bangkok price data should be treated with extreme caution and is excluded from cross-city price ranking narratives below.
  </div>

  <h3>Median Nightly Price by City</h3>
  {img_tag('median_price', 'Median nightly prices')}

  <h3>Price Breakdown by Room Type</h3>
  <p>The room-type premium varies significantly. Entire homes command 1.5–2.5x the rate of private rooms in most markets. Hotel rooms, where present, typically price between the two.</p>
  {img_tag('price_room_type', 'Price by room type')}
  {price_rt_table}

  <h3>Price Dispersion</h3>
  <p>Beyond medians, understanding price spread is critical. London and Barcelona show wide IQR ranges, reflecting diverse supply from budget to luxury. Rome's distribution is comparatively tight, suggesting a more homogeneous market.</p>
  {img_tag('price_dist', 'Price distribution boxplots')}
</div>

<!-- SECTION 3: SUPPLY STRUCTURE -->
<div class="section" id="supply-structure">
  <h2>3. Supply Structure &amp; Host Concentration</h2>
  <p>The mix of room types and the degree of professional host dominance reveal how "commercialized" each market has become — a signal that directly informs regulatory risk and competitive dynamics.</p>

  <h3>Room-Type Composition</h3>
  <p><strong>{C['top_eh_city']}</strong> leads in Entire Home share at <strong>{C['top_eh_val']:.1f}%</strong>, while <strong>{C['low_eh_city']}</strong> has the lowest at <strong>{C['low_eh_val']:.1f}%</strong>. Markets with higher entire-home shares tend to face greater regulatory scrutiny, as these listings most directly compete with residential housing stock.</p>
  {img_tag('room_mix', 'Room-type composition')}
  {room_table}

  <h3>Professional Host Concentration (≥5 Listings)</h3>
  <p>Professional hosts — those managing 5 or more listings — are a key indicator of market commercialization. <strong>{C['top_pro_city']}</strong> leads with <strong>{C['top_pro_val']:.1f}%</strong> of listings controlled by professional operators, compared to just <strong>{C['low_pro_val']:.1f}%</strong> in <strong>{C['low_pro_city']}</strong>.</p>

  <div class="kpi-grid">
    {kpi_card("Highest Pro Share", f"{C['top_pro_val']:.1f}%", C['top_pro_city'], "#dc2626")}
    {kpi_card("Lowest Pro Share", f"{C['low_pro_val']:.1f}%", C['low_pro_city'], "#059669")}
  </div>

  {img_tag('pro_host', 'Professional host concentration')}
  {pro_table}

  <div class="callout">
